import csv

with open('outputs/t09_poi_nearest_stop.csv', 'r', encoding='utf-8') as f:
    reader = csv.reader(f)
    header = next(reader)
    row_num = 0
    for row in reader:
        row_num += 1
        if len(row) != 6:
            print(f'Row {row_num} has {len(row)} fields instead of 6')
            print(f'  Content: {row}')
        # Check for unquoted commas or quotes in fields
        for i, field in enumerate(row):
            if ',' in field and '\"' not in field:
                print(f'Row {row_num}, field {i+1} has comma but not quoted: {field}')
            if '\"' in field and '\"\"' not in field:
                print(f'Row {row_num}, field {i+1} has quote but not escaped: {field}')
print('Validation complete')
